CREATE OR REPLACE FUNCTION public.acceso_password_club(p_email text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE e text:=lower(trim(p_email)); u record; BEGIN IF NOT public.has_club_role('directiva') THEN RAISE EXCEPTION 'No autorizado'; END IF; IF NOT EXISTS(SELECT 1 FROM public.usuario_roles WHERE email=e AND activo AND (public.is_super_admin() OR rol IN ('socia','negocio'))) OR (NOT public.is_super_admin() AND EXISTS(SELECT 1 FROM public.usuario_roles WHERE email=e AND activo AND rol IN ('directiva','super_admin'))) THEN RAISE EXCEPTION 'No autorizado'; END IF; SELECT id,coalesce(encrypted_password,'')<>'' AS password_ready, email_confirmed_at IS NOT NULL AS confirmed INTO u FROM auth.users WHERE lower(email)=e LIMIT 1; IF NOT FOUND THEN RETURN jsonb_build_object('user_id',NULL,'activo',false); END IF; RETURN jsonb_build_object('user_id',u.id,'activo',u.password_ready AND u.confirmed); END $$;
REVOKE ALL ON FUNCTION public.acceso_password_club(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.acceso_password_club(text) TO authenticated, service_role;